1	package geminicli
2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"io"
8		"os"
9		"time"
10	
11		"github.com/entireio/cli/cmd/entire/cli/agent"
12	)
13	
14	// Compile-time interface assertions for new interfaces.
15	var (
16		_ agent.TranscriptAnalyzer = (*GeminiCLIAgent)(nil)
17		_ agent.TokenCalculator    = (*GeminiCLIAgent)(nil)
18		_ agent.HookResponseWriter = (*GeminiCLIAgent)(nil)
19	)
20	
21	// WriteHookResponse outputs a hook response message as plain text to stdout.
22	//
23	// Why plain text and not JSON? Gemini CLI (as of v0.40.0) double-displays
24	// systemMessage when it arrives in JSON form: once via emitHookSystemMessage
25	// (rendered with the [hookName] source tag) and again via the SessionStart
26	// path's direct historyManager.addItem (rendered without a tag). With plain
27	// text, gemini's convertPlainTextToHookOutput synthesizes a systemMessage
28	// internally, the JSON-only emitHookSystemMessage event doesn't fire, and
29	// the user sees the banner exactly once.
30	func (g *GeminiCLIAgent) WriteHookResponse(message string) error {
31		if message == "" {
32			return nil
33		}
34		if _, err := fmt.Fprintln(os.Stdout, message); err != nil {
35			return fmt.Errorf("failed to write hook response: %w", err)
36		}
37		return nil
38	}
39	
40	// HookNames returns the hook verbs Gemini CLI supports.
41	// These become subcommands: entire hooks gemini <verb>
42	func (g *GeminiCLIAgent) HookNames() []string {
43		return []string{
44			HookNameSessionStart,
45			HookNameSessionEnd,
46			HookNameBeforeAgent,
47			HookNameAfterAgent,
48			HookNameBeforeModel,
49			HookNameAfterModel,
50			HookNameBeforeToolSelection,
51			HookNameBeforeTool,
52			HookNameAfterTool,
53			HookNamePreCompress,
54			HookNameNotification,
55		}
56	}
57	
58	// ParseHookEvent translates a Gemini CLI hook into a normalized lifecycle Event.
59	// Returns nil if the hook has no lifecycle significance (e.g., pass-through hooks).
60	func (g *GeminiCLIAgent) ParseHookEvent(_ context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
61		switch hookName {
62		case HookNameSessionStart:
63			return g.parseSessionStart(stdin)
64		case HookNameBeforeAgent:
65			return g.parseTurnStart(stdin)
66		case HookNameAfterAgent:
67			return g.parseTurnEnd(stdin)
68		case HookNameSessionEnd:
69			return g.parseSessionEnd(stdin)
70		case HookNamePreCompress:
71			return g.parseCompaction(stdin)
72		case HookNameBeforeModel:
73			return g.parseBeforeModel(stdin)
74		case HookNameBeforeTool, HookNameAfterTool,
75			HookNameAfterModel, HookNameBeforeToolSelection, HookNameNotification:
